assert t.count("  box.append(el('p', 'It will not invent a warning, an observation, a water level or a forecast, and it says when evidence is missing rather than filling the gap. Official warning applicability, live station observations and field, marine or travel clearance are not connected.', 'welcome-limit'));") == 1, 'limit anchor'
t = t.replace("  box.append(el('p', 'It will not invent a warning, an observation, a water level or a forecast, and it says when evidence is missing rather than filling the gap. Official warning applicability, live station observations and field, marine or travel clearance are not connected.', 'welcome-limit'));", "  box.append(el('p', 'It will not invent a warning, an observation, a water level or a forecast, and it says when evidence is missing rather than filling the gap. Radar and satellite imagery, sea-area and coastal bulletins, flood extent and any delivery are not connected, and every answer says so where it matters.', 'welcome-limit'));\n  box.append(el('p', 'Answering with the rules floor and whatever models this machine has configured. A cloud key is optional: put one in with python3 scripts/models.py --set-key and the Settings surface shows the state and the ranked free models.', 'welcome-limit'));", 1)
